import 'package:go_router/go_router.dart';import '../routes/app_routes.dart';import '../../services/auth_service.dart';import '../../services/invoice_service.dart';import '../../services/tax_assessment_service.dart';import '../../screens/auth/login_screen.dart';import '../../screens/home/home_screen.dart';import '../../screens/invoices/invoices_screen.dart';import '../../screens/invoices/invoice_form_screen.dart';import '../../screens/assessments/assessments_screen.dart';import '../../screens/assessments/assessment_detail_screen.dart';
GoRouter buildRouter(AuthService auth,InvoiceService invoices,TaxAssessmentService assessments)=>GoRouter(initialLocation:AppRoutes.login,routes:[GoRoute(name:'login',path:AppRoutes.login,builder:(context,state)=>LoginScreen(auth:auth)),GoRoute(name:'home',path:AppRoutes.home,builder:(context,state)=>HomeScreen(auth:auth)),GoRoute(name:'invoices',path:AppRoutes.invoices,builder:(context,state)=>InvoicesScreen(service:invoices)),GoRoute(name:'invoiceNew',path:AppRoutes.invoiceNew,builder:(context,state)=>InvoiceFormScreen(service:invoices)),GoRoute(name:'invoiceEdit',path:'/notas/:id',builder:(context,state)=>InvoiceFormScreen(service:invoices,id:int.parse(state.pathParameters['id']!))),GoRoute(name:'assessments',path:AppRoutes.assessments,builder:(context,state)=>AssessmentsScreen(invoices:invoices,assessments:assessments)),GoRoute(name:'assessmentDetail',path:'/apuracoes/:id',builder:(context,state)=>AssessmentDetailScreen(service:assessments,id:int.parse(state.pathParameters['id']!)))]);
